import prismaMock from '../prisma-mock';
import HttpException from '../../app/models/http-exception.model';
import {
  deleteComment,
  editComment,
  favoriteArticle,
  unfavoriteArticle,
} from '../../app/routes/article/article.service';

describe('ArticleService', () => {
  describe('deleteComment', () => {
    test('should throw an error ', () => {
      // Given
      const id = 123;
      const idUser = 456;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      expect(deleteComment(id, idUser)).rejects.toThrowError();
    });
  });

  describe('favoriteArticle', () => {
    test('should return the favorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      // @ts-ignore
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      // @ts-ignore
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(favoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
      await expect(favoriteArticle(slug, id)).rejects.toThrowError();
    });
  });
  describe('unfavoriteArticle', () => {
    test('should return the unfavorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(unfavoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
      await expect(unfavoriteArticle(slug, id)).rejects.toThrowError();
    });
  });

  describe('editComment', () => {
    const minute = 60 * 1000;
    const now = new Date('2026-10-30T12:00:00.000Z');
    const slug = 'How-to-train-your-dragon';
    const commentId = 1;
    const userId = 123;

    const mockedAuthor = {
      username: 'RealWorld',
      bio: null,
      image: null,
      followedBy: [],
    };

    beforeEach(() => {
      jest.useFakeTimers().setSystemTime(now);
    });

    afterEach(() => {
      jest.useRealTimers();
    });

    test('should save the new body and set editedAt when the author edits within the window', async () => {
      // Given
      const createdAt = new Date(now.getTime() - 5 * minute);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue({
        id: commentId,
        createdAt,
        updatedAt: createdAt,
        body: 'edited body',
        editedAt: now,
        author: mockedAuthor,
      });

      // Then
      const result = await editComment('edited body', slug, commentId, userId);

      expect(prismaMock.comment.update).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: commentId },
          data: { body: 'edited body', editedAt: now },
        }),
      );
      expect(result).toHaveProperty('body', 'edited body');
      expect(result).toHaveProperty('editedAt', now);
    });

    test('should only look up comments written by the current user on the article in the URL', async () => {
      // Given
      const createdAt = new Date(now.getTime() - 1 * minute);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue({
        id: commentId,
        createdAt,
        updatedAt: createdAt,
        body: 'edited body',
        editedAt: now,
        author: mockedAuthor,
      });

      // Then
      await editComment('edited body', slug, commentId, userId);

      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: commentId, authorId: userId, article: { slug } },
        }),
      );
    });

    test('should allow the edit at exactly 30 minutes after creation', async () => {
      // Given
      const createdAt = new Date(now.getTime() - 30 * minute);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue({
        id: commentId,
        createdAt,
        updatedAt: createdAt,
        body: 'edited body',
        editedAt: now,
        author: mockedAuthor,
      });

      // Then
      await expect(editComment('edited body', slug, commentId, userId)).resolves.toHaveProperty(
        'editedAt',
        now,
      );
    });

    test('should refuse the edit after the 30 minute window', async () => {
      // Given
      const createdAt = new Date(now.getTime() - 30 * minute - 1);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });

      // Then
      await expect(editComment('edited body', slug, commentId, userId)).rejects.toBeInstanceOf(
        HttpException,
      );
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should refuse the edit when no comment of this user matches', async () => {
      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(editComment('edited body', slug, commentId, userId)).rejects.toBeInstanceOf(
        HttpException,
      );
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should return 422 with the error body when the body is blank', async () => {
      // Then
      await expect(editComment('', slug, commentId, userId)).rejects.toMatchObject({
        errorCode: 422,
        message: { errors: { body: ["can't be blank"] } },
      });
      expect(prismaMock.comment.findFirst).not.toHaveBeenCalled();
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });
  });
});

